/* From Uiverse.io by vikramsinghnegi  - Tags: simple, button, switch */
.__UIV_SCOPE__ .onoffswitch {
  position: relative;
  width: 90px;
  user-select: none;
}
.__UIV_SCOPE__ .onoffswitch-checkbox {
  display: none;
}
.__UIV_SCOPE__ .onoffswitch-label {
  display: block;
  overflow: hidden;
  cursor: pointer;
  border: 2px solid #999999;
  border-radius: 20px;
}
.__UIV_SCOPE__ .onoffswitch-inner {
  width: 200%;
  margin-left: -100%;
  transition: margin 0.3s ease-in 0s;
}
.__UIV_SCOPE__ .onoffswitch-inner:before,
.__UIV_SCOPE__ .onoffswitch-inner:after {
  float: left;
  width: 50%;
  height: 30px;
  padding: 0;
  line-height: 30px;
  font-size: 14px;
  color: white;
  font-family: Trebuchet, Arial, sans-serif;
  font-weight: bold;
  box-sizing: border-box;
}
.__UIV_SCOPE__ .onoffswitch-inner:before {
  content: "ON";
  padding-left: 10px;
  background-color: #212f33;
  color: #ffffff;
}
.__UIV_SCOPE__ .onoffswitch-inner:after {
  content: "OFF";
  padding-right: 10px;
  background-color: #eeeeee;
  color: #999999;
  text-align: right;
}
.__UIV_SCOPE__ .onoffswitch-switch {
  width: 18px;
  margin: 6px;
  background: #ffffff;
  border: 2px solid #271616;
  border-radius: 20px;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 56px;
  transition: all 0.3s ease-in 0s;
}
.__UIV_SCOPE__ .onoffswitch-checkbox:checked + .onoffswitch-label .onoffswitch-inner {
  margin-left: 0;
}
.__UIV_SCOPE__ .onoffswitch-checkbox:checked + .onoffswitch-label .onoffswitch-switch {
  right: 0px;
}
